<script setup lang="ts">
import { Head, Link } from '@inertiajs/vue3';
import DashboardLayout from '../layouts/DashboardLayout.vue';
import type { School, SchoolDashboard } from '../types';
defineProps<{snapshot:Record<string,any>;schools:School[];selectedSchool:School|null;dashboard:SchoolDashboard|null}>();
const printReport=()=>window.print();
</script>
<template><Head :title="`${snapshot.student_name} – Report Card`"/><DashboardLayout page="report-card" title="Student Report Card" :schools="schools" :selected-school="selectedSchool" :dashboard="dashboard"><div class="academic-actions no-print report-toolbar"><Link :href="`/preview/schools/${selectedSchool?.slug}/academic/operations/results`" class="secondary-button">Back to results</Link><button class="academic-button" @click="printReport">Print A4 report card</button></div><article class="report-card-sheet"><header class="report-school"><img :src="snapshot.school_logo" alt="School emblem" width="64" height="64"/><div><h1>{{ snapshot.school_name }}</h1><p>Student Academic Report</p><strong>{{ snapshot.exam_name }}</strong></div><span :class="{'draft-watermark':snapshot.publication==='draft'}">{{ snapshot.publication==='draft'?'DRAFT / NOT PUBLISHED':`PUBLISHED · V${snapshot.version}` }}</span></header><dl class="report-student"><div><dt>Student</dt><dd>{{ snapshot.student_name }}</dd></div><div><dt>Admission number</dt><dd>{{ snapshot.admission_number }}</dd></div><div><dt>Academic session</dt><dd>{{ snapshot.session }}</dd></div><div><dt>Class / section</dt><dd>{{ snapshot.class }} / {{ snapshot.section }}</dd></div></dl><table class="report-marks"><thead><tr><th>Subject</th><th>Maximum</th><th>Obtained</th><th>Percentage</th><th>Grade</th><th>Status</th></tr></thead><tbody><tr v-for="row in snapshot.subjects" :key="row.subject_id"><td>{{ row.subject }}</td><td>{{ row.maximum_marks }}</td><td>{{ row.status==='scored'?row.obtained_marks:row.status==='absent'?'Absent':row.status==='exempt'?'Exempt':'Unmarked' }}</td><td>{{ row.percentage!==null?row.percentage+'%':'—' }}</td><td>{{ row.grade??'—' }}</td><td>{{ row.status==='exempt'?'Exempt':row.passed===null?'Pending':row.passed?'Pass':'Fail' }}</td></tr></tbody><tfoot><tr><th>Total</th><td>{{ snapshot.maximum_marks }}</td><td>{{ snapshot.outcome==='incomplete'?'Pending':snapshot.obtained_marks }}</td><td>{{ snapshot.percentage!==null?snapshot.percentage+'%':'—' }}</td><td>{{ snapshot.grade??'—' }}</td><td>{{ snapshot.outcome }}</td></tr></tfoot></table><div class="report-outcome"><strong>Overall result: {{ snapshot.outcome.toUpperCase() }}</strong><span v-if="snapshot.ranking_enabled">Position: {{ snapshot.rank??'Not ranked' }} · Ties use competition ranking</span></div><section class="report-remarks"><h2>Teacher remarks</h2><p v-for="row in snapshot.subjects.filter((r:any)=>r.remarks)" :key="row.subject_id"><strong>{{ row.subject }}:</strong> {{ row.remarks }}</p><p v-if="!snapshot.subjects.some((r:any)=>r.remarks)">No remarks recorded.</p></section><div class="report-signatures"><span>Class teacher</span><span>Principal / authorized signatory</span></div><footer><span>{{ snapshot.publication==='draft'?'Draft preview from current marks; missing marks are not treated as zero.':'Immutable published snapshot. Grading changes do not alter this document.' }}</span><small>{{ snapshot.scheme_name }} · {{ snapshot.published_at??'Unpublished' }}</small><small>Local development record · no authenticated signatory</small></footer></article></DashboardLayout></template>
